(function(root){'use strict';const M=root.BudgetModel||(typeof require==='function'?require('./model.js'):null),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function narrative(r,c){
 const out=[],rr=c.roomResults.find(x=>x.id===r.id)||{};
 for(const g of r.recessGroups.filter(g=>M.q(g.qty)))out.push(`Livewire will supply and install ${M.q(g.qty)} ${g.adjustable?'adjustable':'fixed'} ${M.BEHAVIORS[g.behavior]||'recessed'} recessed lights${r.install==='retrofit'?' at the existing lighting locations':''}.`);
 if(M.q(r.linearFt))out.push(`We will supply and install approximately ${M.q(r.linearFt)} feet of ${M.LINEAR_BEHAVIORS[r.linearBehavior]||'linear'} undercabinet lighting, including the selected channels, power equipment, connections and lighting controls.`);
 if(M.q(r.decorNew))out.push(`We will install ${M.q(r.decorNew)} owner-supplied decorative ${M.q(r.decorNew)===1?'fixture':'fixtures'} at new locations, including the required boxes and wiring.`);
 if(M.q(r.decorExisting))out.push(`We will replace ${M.q(r.decorExisting)} existing decorative ${M.q(r.decorExisting)===1?'fixture':'fixtures'} with owner-supplied fixtures, using suitable existing wiring and support.`);
 if(M.q(r.fanQty))out.push(r.fanWork==='new'?`We will install ${M.q(r.fanQty)} owner-supplied ceiling ${M.q(r.fanQty)===1?'fan':'fans'} at new locations with fan-rated support and new wiring.`:r.fanWork==='replace'?`We will remove ${M.q(r.fanQty)} existing ceiling ${M.q(r.fanQty)===1?'fan':'fans'} and install owner-supplied replacements, including the selected support work and connection to suitable existing wiring.`:`We will retain ${M.q(r.fanQty)} existing ceiling ${M.q(r.fanQty)===1?'fan':'fans'} and provide only the selected controls.`);
 if(M.q(r.fanQty)&&r.fanWork==='replace'&&r.fanSupport!=='verified')out.push('The budget includes replacement fan-rated boxes and support braces because existing support has not been confirmed suitable.');
 if((c.materials||[]).some(x=>x.groupId===r.id&&x.priceBasis==='comparable-allowance'))out.push('The selected recessed-light assemblies include a conservative allowance for standard white decorative trims. Final trim selection will be checked against that allowance during design.');
 if(rr.keypadQty)out.push(`We will install ${rr.keypadQty} lighting ${rr.keypadQty===1?'keypad':'keypads'} and configure the agreed room controls.`);
 for(const g of (r.shadeGroups||[]).filter(g=>M.q(g.qty))){const n=M.q(g.qty)*M.q(g.layers||1);out.push(`We will supply, install and test ${n} ${M.Shade.FAMILIES[g.family]||'Lutron'} ${g.style} ${n===1?'shade':'shades'} for openings approximately ${g.widthFt||'?'} by ${g.heightFt||'?'} feet, including the selected power and control equipment. Final measurements and fabric selections will be confirmed before ordering.`);out.push((g.family==='palladiom_wired'||g.communication==='wired'?'Shade commands use wired QS communication.':'Shade commands use wireless communication.')+' '+(g.power==='battery'?'Battery power is included; no new shade power cable is carried.':g.power==='existing'?'Compatible existing wired power will be checked and reused.':'New wired shade power and a compatible supply are included.'));}
 out.push(...(rr.scope||[]).filter(x=>!x.startsWith('Install owner-supplied ceiling fans')&&!x.startsWith('Remove existing fans')&&!x.startsWith('Retain the existing ceiling fans')&&!x.startsWith('Install the lighting keypads')&&!x.startsWith('Measure, install and test')));
 return out;
}
function build(s,c){const range=M.range(c,s.config);return{company:'Livewire',example:s.pricingExample===true,name:String(s.project.name||'Lighting project'),installationDate:s.project.date,system:{none:'Conventional controls',RA3:'RadioRA 3',HomeWorks:'HomeWorks'}[s.project.system]||'To be confirmed',preparedDate:new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'long',day:'numeric'}).format(new Date()),range,rooms:s.rooms.map(r=>({name:String(r.name),narrative:narrative(r,c),installation:M.BUILDS[r.install]||'To be confirmed',scope:c.roomResults.find(room=>room.id===r.id)?.scope||[],lights:r.recessGroups.filter(g=>M.q(g.qty)).map(g=>`${g.qty} ${g.adjustable?'adjustable':'standard'} ${M.BEHAVIORS[g.behavior]||'recessed'} lights`),linearFt:M.q(r.linearFt),decorative:M.q(r.decorNew)+M.q(r.decorExisting),fans:M.q(r.fanQty),fanWork:r.fanWork||'controls',keypads:c.roomResults.find(room=>room.id===r.id)?.keypadQty||0,shades:(r.shadeGroups||[]).filter(g=>M.q(g.qty)).map(g=>`${M.q(g.qty)*M.q(g.layers||1)} ${M.Shade.FAMILIES[g.family]||'Lutron'} ${g.style} ${M.q(g.qty)*M.q(g.layers||1)===1?'shade':'shades'}, approximate ${g.widthFt||'?'} × ${g.heightFt||'?'} ft`)})),sharedScope:[...(c.processors||c.gateways?(s.project.system==='HomeWorks'?['Provide a Lutron HomeWorks control system'+(s.rooms.some(r=>r.recessGroups.some(g=>M.q(g.qty)&&['ketra','rania'].includes(g.behavior))||(M.q(r.linearFt)&&r.linearBehavior==='rania'))?' to support the selected Ketra or Rania lighting.': ' for the selected lighting and keypad arrangement.')]:s.project.system==='RA3'?['Provide a Lutron RadioRA 3 control system for the selected lighting and shades.']:[]):[]),...(c.processors||c.gateways?['Connect the lighting-control equipment to the available property network. The budget assumes an operational network is provided; network installation and upgrades are excluded.']:[]),...(c.processors||c.gateways?['Install the shared lighting-control equipment, configure the agreed basic scenes, test operation and provide an owner handoff.']:[]),...(c.panelCount?['Install the central lighting panels and connect their assigned lighting loads.']:[]),...M.Installation.sharedScope(c.routes||[])],assumptions:['A preliminary planning budget, not a fixed quote or installation design. Final scope, site conditions and equipment selections require confirmation.','The room scope identifies the installation method. Route lengths and access-removal quantities are planning allowances pending verification. New fixture and box cutouts are separate from additional routing openings. Changes to the agreed scope or confirmed site conditions require review.',...(c.planningBudget?['The budget uses company equipment and installation allowances. Existing circuits are assumed suitable for the selected loads. Final load assignments, device placement, wireless coverage and programming will be coordinated during design. Unconfirmed existing-system compatibility or physical wiring restrictions must be resolved separately.']:[]),'One two-person installation crew is assumed. Applicable selected travel allowance is included when a completed range is available.','Decorative fixtures and ceiling fans are owner supplied. Selected fan installation is included only where listed in the room scope. Drywall or plaster repair, painting, structural work and service upgrades are excluded.',...(c.shades?.rows?.some(x=>x.basis?.startsWith('Upper historical'))?['Shade equipment is budgeted at the upper historical allowance for each selected size, not a current fabrication quote. Final fabric and options must fit that allowance or be repriced before commitment.']:[]),'Shade dimensions are preliminary. Fabric, complete assembly, power, mounting and final measurements must be confirmed before ordering. Blackout fabric alone does not eliminate light gaps.', 'The completed range includes applicable shipping and handling and the configured materials surcharge.']};}
function html(d,logo=''){const money=(x,cents=0)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:cents,maximumFractionDigits:cents}).format(x);return `<article class="customer-sheet"><header class="customer-brand">${logo.startsWith('data:image/')?`<img src="${E(logo)}" alt="Livewire">`:'<strong>LIVEWIRE</strong>'}<span>${d.example?'INTERNAL EXAMPLE · LIGHTING & SHADES':'LIGHTING & SHADES BUDGET'}</span></header><div class="customer-heading"><p>Prepared ${E(d.preparedDate)}</p><h1>${E(d.name)}</h1><p>${E(d.system)} · Planned installation ${E(d.installationDate)}</p></div><section class="customer-range"><span>${d.range?'PRELIMINARY BUDGET RANGE · USD':'SCOPE SUMMARY · BUDGET INCOMPLETE'}</span><h2>${d.range?money(d.range.low)+' – '+money(d.range.high):'Budget pending'}</h2><p>${d.range?(d.example?'Demonstration using historical shade allowances and a public remote price.':'A planning range for the scope below. Subject to the assumptions and exclusions listed.'):'No dollar estimate is being presented. Pricing, installation allowances and required reviews must be completed first.'}</p>${d.range&&!d.example&&Number.isFinite(d.range.designRetainer)?`<p><strong>Design retainer ${money(d.range.designRetainer,2)}</strong><br>4% of the low end of the budget. Livewire credits this amount toward the project if you proceed.</p>`:''}</section><h2>Planned room scope</h2>${d.rooms.length?d.rooms.map(r=>`<section class="customer-room"><h3>${E(r.name)}</h3><p class="customer-room-type">${E(r.installation)}</p>${(r.narrative||r.scope||[]).map(line=>`<p>${E(line)}</p>`).join('')||'<p>Scope to be confirmed</p>'}</section>`).join(''):'<p>No rooms have been entered.</p>'}${d.sharedScope?.length?`<h2>Shared installation work</h2>${d.sharedScope.map(x=>`<p>${E(x)}</p>`).join('')}`:''}<h2>Assumptions and exclusions</h2><div class="customer-assumptions">${d.assumptions.map(x=>`<p>${E(x)}</p>`).join('')}</div><footer>Livewire · Preliminary lighting and shades budget · ${d.range?'Not a fixed-price quote':'Incomplete: do not use as a price commitment'}</footer></article>`;}
const api={build,html};root.CustomerReport=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
